const body = $json.body || {};
const data = body.data || {};
const fields = Array.isArray(data.fields) ? data.fields : [];

// Question title prefix (Ukrainian form) -> English column key.
// Edit the left side to match your own Tally question titles.
const MAP = [
  ['У якій сфері', 'industry'],
  ['Як до вас звертатися', 'name'],
  ['E-mail для відповіді', 'email'],
  ['Назва компанії', 'company'],
  ['Сайт або сторінка', 'website'],
  ['Скільки людей працює', 'team_size'],
  ['Хто зараз обробляє', 'lead_handler'],
  ['Звідки приходять заявки', 'lead_sources'],
  ['Скільки заявок', 'lead_volume'],
  ['Що хочете покращити', 'goals'],
  ['Якими системами', 'systems'],
  ['Яка саме CRM', 'other_crm'],
  ['Опишіть задачу', 'task_description'],
  ['Що відбувається після', 'process_steps'],
  ['Де зараз зберігаються', 'data_storage'],
  ['Які готові рішення', 'interest_solutions'],
  ['Який формат співпраці', 'interest_package'],
  ['Коли хочете запустити', 'timeline'],
  ['Якою мовою', 'contact_language'],
  ['Як вам зручніше отримати', 'response_format'],
  ['Де вам зручно поговорити', 'call_channel'],
  ['Номер телефону', 'call_contact'],
  ['Коли вам зручно', 'call_time'],
  ['Як ви про нас', 'referral'],
  ['Згода на обробку', 'consent'],
];
// Tally hidden fields, passed from the page URL (?page=...&utm_source=...)
const HIDDEN = ['lang', 'page', 'format', 'package', 'readiness', 'utm_source', 'utm_medium', 'utm_campaign', 'utm_content'];
// Industries outside the studio focus get a polite "thanks" screen in Tally and are flagged here
const EXCLUDED_INDUSTRY_PREFIX = 'Бухгалтерія';

function toText(f) {
  let v = f.value;
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) {
    const opts = Array.isArray(f.options) ? f.options : [];
    return v.map(x => {
      const o = opts.find(o => o.id === x);
      return o ? o.text : String(x);
    }).join('; ');
  }
  return String(v);
}

const out = {};
for (const f of fields) {
  const label = String(f.label || '').trim();
  if (typeof f.value === 'boolean') continue;
  if (HIDDEN.includes(label)) { out[label] = toText(f); continue; }
  const m = MAP.find(([p]) => label.startsWith(p));
  if (!m) continue;
  const key = m[1];
  if (out[key] !== undefined) continue;
  out[key] = toText(f);
}

const row = {
  submitted_at: data.createdAt || body.createdAt || new Date().toISOString(),
  response_id: data.responseId || data.submissionId || '',
  excluded: String(out.industry || '').startsWith(EXCLUDED_INDUSTRY_PREFIX),
  consent: Boolean(out.consent && out.consent.length),
  raw_json: JSON.stringify(body),
};
for (const [, key] of MAP) if (key !== 'consent') row[key] = out[key] || '';
for (const h of HIDDEN) row[h] = out[h] || '';

return { json: row };
